/**
 * The introduction's anonymous counter (the data plan, owner 22 Oct 2026):
 * each screen of the introduction is counted once per install, so the
 * operators can see which screen visitors stop at. The request carries the
 * screen's name and the app's platform and nothing else: no account, no id,
 * no answer. It is sent once and never retried; a failure, or a server
 * without the endpoint, changes nothing for the visitor.
 *
 * Which screens were sent lives in the small preferences store beside
 * `wb.intro`, so a reload or a second visit does not count them again.
 */
import { me } from '@/api/endpoints.js';
import type { ApiIntroStepInput } from '@/api/types.js';
import { platform } from '@/lib/platform/index.js';

export type IntroStep = ApiIntroStepInput['step'];

const KEY = 'wb.introSteps';

export function countIntroStep(step: IntroStep): void {
  try {
    const sent = (platform.prefs.get(KEY) ?? '').split(',').filter((s) => s !== '');
    if (sent.includes(step)) return;
    platform.prefs.set(KEY, [...sent, step].join(','));
    void me.countIntroStep({ step, platform: platform.env.platform }).catch(() => undefined);
  } catch {
    // A counter is never worth an error on the introduction.
  }
}
